def build():
    strings = {}
    for key, (en, ja, ko, fr) in T.items():
        strings[key] = {"extractionState": "manual", "localizations": {
            "en": {"stringUnit": {"state": "translated", "value": en}},
            "ja": {"stringUnit": {"state": "translated", "value": ja}},
            "ko": {"stringUnit": {"state": "translated", "value": ko}},
            "fr": {"stringUnit": {"state": "translated", "value": fr}},
        }}
    for key, (en, ja, ko, fr, zh) in list(EXISTING.items()) + list(LABS.items()):
        strings[key] = {"extractionState": "manual", "localizations": {
            "zh-Hans": {"stringUnit": {"state": "translated", "value": zh}},
            "en": {"stringUnit": {"state": "translated", "value": en}},
            "ja": {"stringUnit": {"state": "translated", "value": ja}},
            "ko": {"stringUnit": {"state": "translated", "value": ko}},
            "fr": {"stringUnit": {"state": "translated", "value": fr}},
        }}
    return {"sourceLanguage": "zh-Hans", "strings": strings, "version": "1.0"}

if __name__ == "__main__":
    out = os.path.join(os.path.dirname(__file__), "..", "BFStock", "Localizable.xcstrings")
    with open(out, "w", encoding="utf-8") as f:
        json.dump(build(), f, ensure_ascii=False, indent=2, sort_keys=True)
    print("wrote", os.path.normpath(out), len(T) + len(EXISTING) + len(LABS), "keys")
